let raw = '';
try { raw = $input.first().json.candidates[0].content.parts.map(p => p.text || '').join(''); } catch (e) {}
raw = raw.replace(/```json|```/g, '').trim();
try {
  const j = JSON.parse(raw);
  return [{ json: { topic_title: j.topic_title || '', video_concept: j.video_concept || '', content_type: (j.content_type || '').toLowerCase() } }];
} catch (e) {
  return [{ json: { topic_title: '', video_concept: '', content_type: '', parse_error: 'Gemini topic JSON parse failed', raw: raw.slice(0, 400) } }];
}

const fs = require('fs');
const path = '/agency/memory.json';
let mem = { past_topics: [], tone_notes: '', runs: 0 };
try { mem = JSON.parse(fs.readFileSync(path, 'utf8')); } catch (e) {}
const inp = $input.first().json;
const title = inp.topic_title || '';
const duplicate = (mem.past_topics || []).includes(title);
mem.past_topics = [...(mem.past_topics || []), title].filter(Boolean).slice(-50);
mem.runs = (mem.runs || 0) + 1;
try { fs.writeFileSync(path, JSON.stringify(mem, null, 2)); } catch (e) {}
return [{ json: { topic_title: title, video_concept: inp.video_concept || '',
  content_type: inp.content_type || '',
  memory: { past_topics: (mem.past_topics || []).slice(-10), tone_notes: mem.tone_notes || '', runs: mem.runs },
  duplicate_topic: duplicate } }];

let raw = '';
try { raw = $input.first().json.content.map(c => c.text || '').join(''); } catch (e) {}
raw = raw.replace(/```json|```/g, '').trim();
const start = raw.indexOf('{'), end = raw.lastIndexOf('}');
const title = $('3. Chat Memory Manager').first().json.topic_title || '';
try {
  const j = JSON.parse(raw.slice(start, end + 1));
  return [{ json: { topic_title: title, voiceover_text: j.voiceover_text || '', scene_prompts: j.scene_prompts || [] } }];
} catch (e) {
  return [{ json: { topic_title: title, voiceover_text: '', scene_prompts: [], parse_error: 'Claude script JSON parse failed', raw: raw.slice(0, 400) } }];
}

const inp = $input.first().json;
const vo = (inp.voiceover_text || '').toString();
const scenes = Array.isArray(inp.scene_prompts) ? inp.scene_prompts : [];
const words = vo.split(/\s+/).filter(Boolean).length;
const est = Math.round(words / 2.2);
const text = (vo + ' ' + (inp.topic_title || '')).toLowerCase();
let tone = 'warm radio storyteller', music = 'cinematic ambient, soft rhythmic pulse', speed = 0.97;
if (/যুদ্ধ|বীর|বিজয়|সেনা|তরবারি|battle|war|hero/.test(text)) { tone = 'epic dramatic'; music = 'epic cinematic drums and strings'; speed = 1.0; }
else if (/বিজ্ঞান|মহাবিশ্ব|গ্রহ|কীভাবে|কেন|রহস্য|science|space|why|how/.test(text)) { tone = 'curious energetic explainer'; music = 'upbeat curious electronic ambient'; speed = 1.03; }
else if (/করুণা|দয়া|রহমত|মাফ|দোয়া|mercy|forgive/.test(text)) { tone = 'soft heartfelt emotional'; music = 'gentle piano and strings, slow'; speed = 0.94; }
const suffix = ', cinematic color grading, dynamic camera angle, slow push-in, shallow depth of focus, photorealistic';
const polished = scenes.map(s => s.toString().trim().replace(/\.?$/, '') + suffix);
const sentences = vo.split(/(?<=[।?!])\s+/).filter(Boolean);
const caption_lines = polished.map((_, i) => sentences[Math.min(i, sentences.length - 1)] || '');
return [{ json: { topic_title: inp.topic_title || '', voiceover_text: vo, scene_prompts: polished,
  caption_lines,
  plan: { tone, speed, music_mood: music, est_seconds: est, scene_count: polished.length,
          scene_seconds: polished.map(() => Math.max(3, Math.round(est / Math.max(1, polished.length)))),
          motion: { camera: 'slow push-in alternating with lateral pan, direction flips each scene',
                    transition: 'crossfade 0.4s between scenes',
                    caption_animation: 'slide-up with fade',
                    video_preferred: true,
                    fallback: 'Flux stills with strong Ken Burns motion (zoom + pan + slight rotation)' } } } }];

const inp = $input.first().json;
const scenes = Array.isArray(inp.scene_prompts) ? inp.scene_prompts : [];
const caps = Array.isArray(inp.caption_lines) ? inp.caption_lines : [];
const secs = (inp.plan && inp.plan.scene_seconds) || [];
return scenes.map((p, i) => ({ json: { scene_index: i + 1, visual_prompt: p,
  caption: caps[i] || '', seconds: secs[i] || 4 } }));

let scene = {};
try { scene = $('Split Scenes').item.json || {}; } catch (e) {}
const j = $input.first().json;
const pages = (j.query && j.query.pages) || {};
let video_url = '';
for (const k of Object.keys(pages)) {
  const ii = (pages[k].imageinfo || [])[0];
  if (ii && (ii.mime || '').indexOf('video/') === 0 && ii.url) { video_url = ii.url; break; }
}
return [{ json: { scene_index: scene.scene_index || 0, visual_prompt: scene.visual_prompt || '',
  caption: scene.caption || '', seconds: scene.seconds || 4, video_url } }];

const items = $input.all();
const urls = items.map(it => {
  const j = it.json;
  if (j.images && j.images[0]) return j.images[0].url || j.images[0];
  return j.url || '';
}).filter(Boolean);
const clips = items.map(it => ({ scene_index: it.json.scene_index || 0,
  visual_prompt: it.json.visual_prompt || '', caption: it.json.caption || '',
  seconds: it.json.seconds || 4, video_url: it.json.video_url || '' }));
const planner = $('5. Muse Planner').first().json;
return [{ json: { topic_title: planner.topic_title, voiceover_text: planner.voiceover_text,
  plan: planner.plan, caption_lines: planner.caption_lines,
  scene_prompts: planner.scene_prompts, image_urls: urls, clips } }];

const planner = $('5. Muse Planner').first().json;
const imgs = $('Collect Images').first().json;
const crea = $('8. Creatomate Motion').first().json;
const clips = imgs.clips || [];
const scenes = (planner.scene_prompts || []).map((p, i) => ({
  index: i + 1, prompt: p, image_url: (imgs.image_urls || [])[i] || '',
  video_url: (clips[i] && clips[i].video_url) || '',
  caption: (planner.caption_lines || [])[i] || '',
  seconds: (planner.plan && planner.plan.scene_seconds && planner.plan.scene_seconds[i]) || 4
}));
return [{ json: { render_manifest: {
  title: planner.topic_title || 'untitled', format: '1080x1920 vertical + 1920x1080 master',
  voiceover_text: planner.voiceover_text || '', tone: planner.plan && planner.plan.tone,
  music_mood: planner.plan && planner.plan.music_mood, scenes,
  creatomate_render: crea, voiceover: 'audio binary from ElevenLabs node (previous step)',
  motion: (planner.plan && planner.plan.motion) || {},
  motion_rule: 'REAL VIDEO first: use video_url when present; otherwise Flux stills with strong Ken Burns motion. Never reuse old pictures — every run searches fresh clips.',
  note: 'Pilot manifest only — Creatomate render is async; poll its status before publishing.'
} } }];
